// Career facts shared with the CV. carrera.json is GENERATED by the owner's `carrera` skill
// from his single source (Second-Brain, Projects/CV/perfil/logros.yaml): do not edit it by hand.
import { useTranslation } from 'react-i18next';
import carrera from './carrera.json';

export const years = carrera.anos.map((a) => ({ name: a.nombre, years: a.anos }));
export const stack = carrera.stack;
export const wipProjects = carrera.proyectos;

// Returns the language block (experiencia, liderazgo, proyectos, formacion) for the active language.
export function useCarrera() {
  const { i18n } = useTranslation();
  const lang = (i18n.resolvedLanguage || 'en').slice(0, 2);
  return carrera[lang] || carrera.en;
}
